using UnityEngine;
using System.Collections.Generic;
namespace FalloutPort {
public class PortProjectile:MonoBehaviour {
 public Vector3 velocity;public float radius=3,damage=40,fuse=4;public bool gravity;public string kind,weaponId;float age;bool resting;
 void Update(){float dt=Time.deltaTime;if(dt<=0)return;age+=dt;if(kind=="mine"&&resting){if(age>1)foreach(var c in Physics.OverlapSphere(transform.position,2,~(1<<2),QueryTriggerInteraction.Collide)){var bug=c.GetComponentInParent<PortRoach>();var actor=c.GetComponentInParent<PortWorldActor>();if(bug&&!bug.dead||actor&&!actor.dead&&actor.hostile){Explode();return;}}return;}if(gravity)velocity+=Physics.gravity*dt;Vector3 next=transform.position+velocity*dt;RaycastHit hit;if(Physics.SphereCast(transform.position,.045f,velocity.normalized,out hit,velocity.magnitude*dt,~(1<<2),QueryTriggerInteraction.Collide)){transform.position=hit.point+hit.normal*.05f;if(kind=="mine"){velocity=Vector3.zero;resting=true;return;}if(kind=="grenade"){velocity=Vector3.Reflect(velocity,hit.normal)*.45f;}else{var direct=hit.collider.GetComponentInParent<PortRoach>();if(direct)direct.Hit(velocity.normalized,hit.point);var target=hit.collider.GetComponentInParent<PortRangeTarget>();if(target)target.Hit();Explode();return;}}else transform.position=next;if(age>=fuse)Explode();}
 void Explode(){var seen=new HashSet<PortRoach>();var actors=new HashSet<PortWorldActor>();foreach(var c in Physics.OverlapSphere(transform.position,radius,~(1<<2),QueryTriggerInteraction.Collide)){var closest=c.ClosestPoint(transform.position);RaycastHit block;if(Physics.Linecast(transform.position,closest,out block,~(1<<2),QueryTriggerInteraction.Ignore)&&block.collider!=c)continue;var actor=c.GetComponentInParent<PortWorldActor>();if(actor&&actors.Add(actor)){float distance=Vector3.Distance(transform.position,closest);actor.Hit(damage*Mathf.Clamp01(1-distance/Mathf.Max(.01f,radius)),weaponId,closest,(actor.transform.position-transform.position).normalized);}var r=c.GetComponentInParent<PortRoach>();if(r&&seen.Add(r))r.Hit((r.transform.position-transform.position).normalized,closest);var target=c.GetComponentInParent<PortRangeTarget>();if(target)target.Hit();if(c.attachedRigidbody&&!c.attachedRigidbody.isKinematic)c.attachedRigidbody.AddExplosionForce(damage*.2f,transform.position,radius,1,ForceMode.Impulse);var n=c.GetComponentInParent<PortCitizen>();if(n)n.React(transform.position,false);}var g=FindAnyObjectByType<PortGame>();if(g){float distance=Vector3.Distance(g.player.transform.position,transform.position);if(distance<radius&&!Physics.Linecast(transform.position,g.player.view.transform.position,~(1<<2),QueryTriggerInteraction.Ignore))PortSurvival.Instance.Damage(damage*(1-distance/radius));g.Sound("shot");}var flash=new GameObject("Explosion flash").AddComponent<Light>();flash.transform.position=transform.position;flash.color=kind=="plasma"?new Color(.2f,1,.1f):new Color(1,.5f,.1f);flash.range=radius*3;flash.intensity=8;Destroy(flash.gameObject,.16f);Destroy(gameObject);}
}
}
